<?php /** @var \Sysfera\Plugin $sf @var \SysferaStoragerent\Ctx $ctx @var string $lang @var array $rows @var string $q @var array $tenants @var bool $canWrite */
require __DIR__ . '/_nav.php'; ?>
<form class="sr-filter" method="get" action="<?= e($sf->url('/documents')) ?>"><input type="search" name="q" value="<?= e($q) ?>" placeholder="<?= e($sf->t('doc_search_ph')) ?>"><button class="btn"><?= e($sf->t('search')) ?></button></form>
<p class="muted sm"><?= e($sf->t('doc_search_note')) ?></p>
<?php if (!$rows): ?><div class="card empty"><?= e($sf->t('none')) ?></div><?php else: ?><div class="card sr-scroll"><table><thead><tr><th><?= e($sf->t('doc_title')) ?></th><th><?= e($sf->t('col_tenant')) ?></th><th><?= e($sf->t('doc_attached')) ?></th><th><?= e($sf->t('col_date')) ?></th><?php if ($canWrite): ?><th></th><?php endif; ?></tr></thead><tbody>
<?php foreach ($rows as $d): $link = match ($d['owner_type']) { 'tenant' => '/tenant/' . $d['owner_id'], 'contract' => '/contract/' . $d['owner_id'], 'invoice' => '/invoice/' . $d['owner_id'], default => '' }; ?>
<tr><td><a href="<?= e($sf->url('/doc/' . $d['id'])) ?>"><?= e($d['title']) ?></a> <small class="muted"><?= e($d['file_name']) ?></small></td><td><?= e($tenants[(int)($d['tenant_id'] ?? 0)] ?? '') ?></td><td><?= $link !== '' ? '<a href="' . e($sf->url($link)) . '">' . e($sf->t('own_' . $d['owner_type'])) . ' #' . (int)$d['owner_id'] . '</a>' : e($sf->t('own_' . $d['owner_type'])) ?></td><td><?= e(sr_dt((int)$d['created_at'])) ?></td>
<?php if ($canWrite): ?><td><form method="post" action="<?= e($sf->url('/doc/' . $d['id'] . '/delete')) ?>" onsubmit="return confirm('<?= e($sf->t('confirm_delete')) ?>')"><?= csrf_field() ?><input type="hidden" name="back" value="/p/storagerent/documents"><button class="btn sm danger"><?= e($sf->t('delete')) ?></button></form></td><?php endif; ?></tr><?php endforeach; ?></tbody></table></div><?php endif; ?>
